     need(P.xp===30000&&P.runs===17&&P.ext===9&&P.best===4321&&P.netEarn===2500,'ONE: a career counter moved (xp '+P.xp+', runs '+P.runs+', ext '+P.ext+', best '+P.best+', net '+P.netEarn+')');
     r=P.pil||{};
